cd /app && cat > local.py <<'PY'
import subprocess, sys, itertools
OPP=['stone','vampire','paper','snake','g2-clear']; TH=[75,75,75,33,33]
def run(path,o,r,fixed=True):
    a=['pmars','-b','-r',str(r)]+(['-f'] if fixed else [])+[path,f'warriors/{o}.red']
    res=subprocess.run(a,capture_output=True,text=True,cwd='/app')
    l=[x for x in res.stdout.strip().split('\n') if x.startswith('Results:')]
    return int(l[0].split()[1]) if l else None
def bench(src,r=100,fixed=True,tag=''):
    p=f'/tmp/lo{tag}.red'; open(p,'w').write(src)
    ws=[run(p,o,r,fixed) for o in OPP]
    return ws if all(w is not None for w in ws) else None
def gen(dec,gg,bb,mod,pb=9):
    return f""";redcode-94
;name Tuned
;assert CORESIZE==8000
gate    equ clear-{gg}
        org st
bptr    dat     bomb,   {pb}
bomb    dat     #{dec},  {bb}
st      spl     #0,     #0
clear   mov     *bptr,  >gate
        djn.{mod}   clear,  }}bomb
"""
def marg(ws,r=100): return min(w*100//r-t for w,t in zip(ws,TH))
res=[]
for dec in range(2400,4001,50):
    for gg in (4,6,8):
        for bb in (gg+3,gg+5,gg+8,gg+13):
            for mod in ('f','x'):
                src=gen(dec,gg,bb,mod)
                ws=bench(src)
                if ws is None: continue
                res.append((marg(ws),ws,(dec,gg,bb,mod),src))
res.sort(key=lambda x:(-x[0],-sum(x[1])))
for m,ws,p,src in res[:12]: print(m,ws,p,flush=True)
import json; json.dump([[m,ws,p] for m,ws,p,_ in res[:40]],open('/tmp/local.json','w'))
open('/tmp/bestlocal.red','w').write(res[0][3])
PY
