cd /app && cat > search4.py <<'PY'
import subprocess, random, sys
OPP=['stone','vampire','paper','snake','g2-clear']; TH=[75,75,75,33,33]
def bench(src,r=100,tag=''):
    p=f'/tmp/s4{tag}.red'; open(p,'w').write(src); ws=[]
    for o in OPP:
        res=subprocess.run(['pmars','-b','-r',str(r),'-f',p,f'warriors/{o}.red'],capture_output=True,text=True,cwd='/app')
        l=[x for x in res.stdout.strip().split('\n') if x.startswith('Results:')]
        if not l: return None
        ws.append(int(l[0].split()[1]))
    return ws
def gen(K,decs,gg,bb,mod,shared):
    L=[';redcode-94',';name M','        org st']
    L.append(f"gate    equ blk-{gg}")
    L.append('blk')
    for i in range(K):
        g = 'gate' if shared else f'gate{i}'
        if not shared: L.insert(3,f"gate{i}   equ blk-{gg}-{i}")
        L.append(f"bptr{i}  dat     bomb{i}, 0")
        L.append(f"bomb{i}  dat     #{decs[i]},  {bb}")
        L.append(f"clear{i} mov     *bptr{i}, >{g}")
        L.append(f"        djn.{mod}   clear{i}, }}bomb{i}")
    L.append('st      spl     #0,     #0')
    for i in range(1,K): L.append(f"        spl     clear{i}")
    L.append('        jmp     clear0')
    return '\n'.join(L)+'\n'
def marg(ws): return min(w-t for w,t in zip(ws,TH))
res=[]
random.seed(11)
trials=[]
for K in (2,3):
    for base in (2550,3200,3400,3550,3650):
        for spread in (0,60,200):
            decs=[base+spread*i for i in range(K)]
            for gg in (4,8):
                for bb in (gg+4*K+3, gg+4*K+8, gg+4*K+15):
                    for mod in ('f','x'):
                        for shared in (True,False):
                            trials.append((K,decs,gg,bb,mod,shared))
random.shuffle(trials)
for t in trials[:600]:
    src=gen(*t); ws=bench(src)
    if ws is None: continue
    res.append((marg(ws),sum(ws),ws,t,src))
res.sort(key=lambda x:(-x[0],-x[1]))
for m,s,ws,t,src in res[:12]: print(m,ws,t[0],t[1],t[2:5],'shared' if t[5] else 'own',flush=True)
open('/tmp/best4.red','w').write(res[0][4])
PY
